import itertools
import math

def is_valid_polygon(sides):
    # Check if the given sides can form a valid polygon using the triangle inequality theorem
    for i in range(len(sides)):
        if sides[i] >= sum(sides) - sides[i]:
            return False
    return True

def polygon_area(sides):
    # Calculate the area using Brahmagupta's formula for cyclic quadrilaterals
    # This is a simplified version for polygons with up to 4 sides
    n = len(sides)
    if n == 3:
        # Heron's formula for triangles
        s = sum(sides) / 2
        area = math.sqrt(s * (s - sides[0]) * (s - sides[1]) * (s - sides[2]))
    elif n == 4:
        # Brahmagupta's formula for cyclic quadrilaterals
        s = sum(sides) / 2
        area = math.sqrt((s - sides[0]) * (s - sides[1]) * (s - sides[2]) * (s - sides[3]))
    else:
        # For polygons with more than 4 sides, use ear clipping to triangulate and calculate area
        return ear_clipping_area(sides)
    return area

def ear_clipping_area(sides):
    # Implement ear clipping algorithm to triangulate the polygon and calculate area
    n = len(sides)
    if n < 3:
        return 0.0

    # Create a list of points (x, y) assuming a simple polygon
    points = [(0, sides[i]) for i in range(n)]

    # Function to calculate the cross product of vectors AB and AC
    def cross_product(A, B, C):
        return (B[0] - A[0]) * (C[1] - A[1]) - (B[1] - A[1]) * (C[0] - A[0])

    # Function to check if a point is an ear
    def is_ear(A, B, C):
        if cross_product(A, B, C) <= 0:
            return False
        for D in points:
            if D != A and D != B and D != C:
                if point_in_triangle(A, B, C, D):
                    return False
        return True

    # Function to check if a point is inside a triangle
    def point_in_triangle(A, B, C, P):
        return (cross_product(P, A, B) >= 0 and
                cross_product(P, B, C) >= 0 and
                cross_product(P, C, A) >= 0)

    # Triangulate the polygon
    triangles = []
    while len(points) > 3:
        for i in range(len(points)):
            A = points[i]
            B = points[(i + 1) % len(points)]
            C = points[(i + 2) % len(points)]
            if is_ear(A, B, C):
                triangles.append((A, B, C))
                points.remove(B)
                break

    # Add the last triangle
    triangles.append((points[0], points[1], points[2]))

    # Calculate the total area
    total_area = 0.0
    for triangle in triangles:
        A, B, C = triangle
        total_area += abs(cross_product(A, B, C)) / 2.0

    return total_area

